import json
import itertools

def solve_puzzle():
    # Define houses and attributes
    houses = [1, 2]  # left to right
    Names = ["Eric", "Arnold"]
    HouseStyles = ["victorian", "colonial"]
    Heights = ["very short", "short"]
    Educations = ["associate", "high school"]

    n = len(houses)

    solutions = []

    # Iterate over all permutations of each attribute category
    for perm_name in itertools.permutations(Names):
        for perm_style in itertools.permutations(HouseStyles):
            # Clue 2: The person residing in a Victorian house is in the first house.
            if perm_style[0] != "victorian":
                continue

            for perm_height in itertools.permutations(Heights):
                for perm_edu in itertools.permutations(Educations):
                    # Build index lookups
                    idx_name = {perm_name[i]: i for i in range(n)}
                    idx_height = {perm_height[i]: i for i in range(n)}
                    idx_edu = {perm_edu[i]: i for i in range(n)}

                    # Clue 1: The person who is short is directly left of Eric.
                    if not (idx_height["short"] + 1 == idx_name["Eric"]):
                        continue

                    # Clue 3: The person who is short is the person with an associate's degree.
                    if idx_height["short"] != idx_edu["associate"]:
                        continue

                    # If all constraints satisfied, record the solution
                    rows = []
                    for i, house in enumerate(houses):
                        row = [
                            str(house),
                            perm_name[i],
                            perm_style[i],
                            perm_height[i],
                            perm_edu[i],
                        ]
                        rows.append(row)
                    solutions.append(rows)

    # Choose the first solution (should be unique for well-posed puzzles)
    if not solutions:
        raise ValueError("No solution found.")
    rows = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "HouseStyle", "Height", "Education"],
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
